```yaml
name: Auto‑merge Dependabot security PRs

on:
  pull_request:
    types: [opened, synchronize]
    branches: [main]

permissions:
  pull-requests: write

jobs:
  merge-dependabot:
    runs-on: ubuntu-latest
    if: |
      github.event.pull_request.user.login == 'dependabot[bot]' &&
      github.event.pull_request.head.repo.owner.login == github.repository_owner &&
      contains(github.event.pull_request.title, 'security')
    steps:
      - name: Merge Dependabot security PR
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = context.payload.pull_request.number;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const { data: pr } = await github.pulls.get({ owner, repo, pull_number: prNumber });

            if (pr.merged) {
              core.info('PR already merged');
              return;
            }

            if (pr.user.login !== 'dependabot[bot]') {
              core.info('Not a Dependabot PR');
              return;
            }

            if (!pr.labels.some(l => l.name === 'security')) {
              core.info('PR not labeled security');
              return;
            }

            try {
              await github.pulls.merge({
                owner,
                repo,
                pull_number: prNumber,
                merge_method: 'squash',
                commit_title: `Merge ${pr.title}`,
                commit_message: pr.body
              });
              core.info('Merged PR');
            } catch (error) {
              core.error(`Failed to merge PR: ${error}`);
            }
